from pathlib import Path
import py_compile

ROOT = Path.cwd()
APP = ROOT / 'app'
T = APP / 'templates'
S = APP / 'static'
MAIN = APP / 'main.py'
ACCESS = APP / 'access_control.py'

for required in (MAIN, ACCESS, T / 'base.html', S / 'styles.css'):
    if not required.exists():
        raise SystemExit(f'Arquivo nao encontrado: {required}')

base = '''<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{% block title %}Gestao de Acessos{% endblock %}</title>
  <link rel="stylesheet" href="{{ url_for('static', path='/styles.css') }}">
  <link rel="stylesheet" href="{{ url_for('static', path='/portal.css') }}">
  {% block head %}{% endblock %}
</head>
<body>
<header class="topbar">
  <a class="brand" href="{% if user is defined and user %}/portal{% else %}/{% endif %}">Gestao de Acessos</a>
  <nav>
    {% if user is defined and user %}
      <a href="/portal">Inicio</a>
      <a href="/portal/funcionarios">Usuarios</a>
      <a href="/portal/perfis">Perfis</a>
      <a href="/portal/propostas">Propostas</a>
      {% if user.role in ['ADMIN_TI','ANALISTA_TI'] %}
        <a href="/comparar">Comparar</a>
        <a href="/admin/contas">Contas</a>
      {% endif %}
      <span class="nav-scope">{{ user.department.nome if user.department else 'T.I. - Todos os departamentos' }}</span>
      <form action="/logout" method="post" class="logout-form"><button type="submit">Sair</button></form>
    {% else %}
      <a href="/login">Entrar</a>
    {% endif %}
  </nav>
</header>
<main class="container">{% block content %}{% endblock %}</main>
<script src="{{ url_for('static', path='/classic-tree.js') }}"></script>
<script src="{{ url_for('static', path='/comparison.js') }}"></script>
{% block scripts %}{% endblock %}
</body>
</html>
'''
(T / 'base.html').write_text(base, encoding='utf-8', newline='\n')

portal_templates = {
'login.html': '''{% extends "base.html" %}{% block title %}Entrar | Gestao de Acessos{% endblock %}{% block content %}<section class="auth-shell"><form class="auth-card" method="post"><div class="auth-mark">GA</div><h1>Gestao de Acessos</h1><p>Entre com sua conta corporativa para acessar o seu departamento.</p>{% if error %}<div class="alert error">{{ error }}</div>{% endif %}<label>E-mail<input name="email" type="email" autocomplete="username" required autofocus></label><label>Senha<input name="password" type="password" autocomplete="current-password" required></label><button class="primary wide">Entrar</button></form></section>{% endblock %}''',
'portal.html': '''{% extends "base.html" %}{% block title %}Inicio | Gestao de Acessos{% endblock %}{% block content %}<section class="hero"><p class="eyebrow">Ambiente autenticado</p><h1>Ola, {{ user.name }}</h1><p>{{ user.department.nome if user.department else 'Administracao de T.I.' }} · {{ user.role|replace('_',' ')|title }}</p></section><section class="cards portal-metrics"><article><span>Funcionarios no seu escopo</span><strong>{{ employee_count }}</strong><a href="/portal/funcionarios">Consultar</a></article><article><span>Propostas no seu escopo</span><strong>{{ proposal_count }}</strong><a href="/portal/propostas">Consultar</a></article><article><span>Novo perfil</span><strong>+</strong><a href="/portal/propostas/nova">Criar proposta</a></article></section>{% endblock %}''',
'portal_employees.html': '''{% extends "base.html" %}{% block title %}Usuarios | Gestao de Acessos{% endblock %}{% block content %}<section class="hero compact"><p class="eyebrow">Escopo departamental</p><h1>Usuarios</h1><p>{% if user.department %}Somente funcionarios de {{ user.department.nome }}.{% else %}Todos os departamentos autorizados para T.I.{% endif %}</p></section><section class="people-grid">{% for employee in employees %}<a class="person-card" href="/portal/funcionarios/{{ employee.id }}"><strong>{{ employee.nome }}</strong><span>{{ employee.login }}</span><small>{{ employee.departamento.nome if employee.departamento else 'Sem departamento' }}</small></a>{% else %}<article class="panel">Nenhum funcionario no seu escopo.</article>{% endfor %}</section>{% endblock %}''',
'portal_employee.html': '''{% extends "base.html" %}{% block title %}{{ employee.nome }}{% endblock %}{% block content %}<a class="back" href="/portal/funcionarios">Voltar para usuarios</a><section class="hero compact"><p class="eyebrow">Usuario do departamento</p><h1>{{ employee.nome }}</h1><p>{{ employee.login }} · {{ employee.departamento.nome }}</p></section><section class="panel"><h2>Perfis vinculados</h2><div class="chips">{% for link in employee.perfis %}<a href="/portal/perfis/{{ link.perfil.id }}">{{ link.perfil.nome }}</a>{% else %}<span>Nenhum perfil vinculado.</span>{% endfor %}</div></section><section class="panel"><p>Para consultar a arvore consolidada deste usuario, use a visualizacao integrada abaixo.</p><a class="button" href="/funcionarios/{{ employee.id }}">Abrir arvore de acessos</a></section>{% endblock %}''',
'proposals.html': '''{% extends "base.html" %}{% block title %}Propostas | Gestao de Acessos{% endblock %}{% block content %}<section class="hero compact"><p class="eyebrow">Perfis gerados no sistema</p><h1>Propostas de perfil</h1><p>As propostas permanecem separadas dos perfis importados do ERP.</p></section><div class="panel-title"><h2>Propostas no seu escopo</h2><a class="button" href="/portal/propostas/nova">Nova proposta</a></div><section class="proposal-list">{% for p in proposals %}<a href="/portal/propostas/{{ p.id }}"><div><strong>{{ p.name }}</strong><span>{{ p.department.nome }} · {{ p.origin|replace('_',' ')|title }}</span></div><em class="flow-status {{ p.workflow_status|lower }}">{{ p.workflow_status|replace('_',' ') }}</em></a>{% else %}<article class="panel">Nenhuma proposta encontrada.</article>{% endfor %}</section>{% endblock %}''',
'proposal_new.html': '''{% extends "base.html" %}{% block title %}Nova proposta{% endblock %}{% block content %}<a class="back" href="/portal/propostas">Voltar para propostas</a><section class="hero compact"><p class="eyebrow">Criacao de perfil</p><h1>Nova proposta</h1><p>O perfil sera criado dentro do departamento autorizado para sua conta.</p></section><form class="panel integrated-form" method="post"><label>Nome da proposta<input name="name" required></label><label>Departamento<select name="department_id" required>{% for d in departments %}<option value="{{ d.id }}">{{ d.nome }}</option>{% endfor %}</select></label><label>Como iniciar?<select name="origin" id="proposal-origin" required><option value="CRIADO_VAZIO">Perfil vazio</option><option value="COPIADO_DE_PERFIL">Copiar perfil existente</option><option value="CONSOLIDADO_FUNCIONARIO">Consolidado de funcionario</option><option value="CONSOLIDADO_DEPARTAMENTO_COMUM">Base comum do departamento</option><option value="CONSOLIDADO_DEPARTAMENTO_UNIAO">Uniao do departamento</option></select></label><label data-source="profile">Perfil base<select name="source_profile_id"><option value="">Selecione</option>{% for p in profiles %}<option value="{{ p.id }}">{{ p.nome }}</option>{% endfor %}</select></label><label data-source="employee">Funcionario base<select name="source_employee_id"><option value="">Selecione</option>{% for e in employees %}<option value="{{ e.id }}">{{ e.nome }}</option>{% endfor %}</select></label><label class="full">Descricao<textarea name="description"></textarea></label><label class="full">Justificativa<textarea name="justification"></textarea></label><div class="alert warning full">A uniao departamental pode combinar acessos excepcionais de pessoas diferentes e exige revisao da T.I.</div><div class="full"><button class="primary">Criar proposta</button></div></form>{% endblock %}{% block scripts %}<script>const o=document.getElementById('proposal-origin');function sync(){document.querySelector('[data-source="profile"]').hidden=o.value!=='COPIADO_DE_PERFIL';document.querySelector('[data-source="employee"]').hidden=o.value!=='CONSOLIDADO_FUNCIONARIO'}o.addEventListener('change',sync);sync();</script>{% endblock %}''',
'proposal_detail.html': '''{% extends "base.html" %}{% block title %}{{ proposal.name }}{% endblock %}{% block content %}<a class="back" href="/portal/propostas">Voltar para propostas</a><section class="hero compact"><p class="eyebrow">{{ proposal.origin|replace('_',' ')|title }}</p><h1>{{ proposal.name }}</h1><p>{{ proposal.department.nome }} · {{ proposal.workflow_status|replace('_',' ') }}</p></section><section class="panel"><p>{{ proposal.description or 'Sem descricao.' }}</p><p><strong>Justificativa:</strong> {{ proposal.justification or 'Nao informada.' }}</p></section><section class="panel"><div class="panel-title"><h2>Acessos da proposta</h2><span>{{ proposal.accesses|length }} itens</span></div><div class="access-list">{% for item in proposal.accesses %}<div><span>{{ item.access.caminho_completo }} › {{ item.access.tela_final }} › {{ item.access.botao }}</span><b class="permission {{ item.status|lower }}">{{ item.status }}</b></div>{% else %}<p>Proposta vazia.</p>{% endfor %}</div></section>{% if proposal.workflow_status in ['RASCUNHO','DEVOLVIDO'] %}<form method="post" action="/portal/propostas/{{ proposal.id }}/enviar"><button class="primary">Enviar para T.I.</button></form>{% endif %}{% if user.role in ['ADMIN_TI','ANALISTA_TI'] and proposal.workflow_status == 'EM_REVISAO' %}<section class="review-grid"><form class="panel" method="post" action="/admin/propostas/{{ proposal.id }}/aprovar"><textarea name="details" placeholder="Parecer"></textarea><button class="approve">Aprovar</button></form><form class="panel" method="post" action="/admin/propostas/{{ proposal.id }}/devolver"><textarea name="details" placeholder="Ajustes necessarios"></textarea><button class="return">Devolver</button></form><form class="panel" method="post" action="/admin/propostas/{{ proposal.id }}/rejeitar"><textarea name="details" placeholder="Motivo"></textarea><button class="reject">Rejeitar</button></form></section>{% endif %}{% endblock %}''',
'accounts.html': '''{% extends "base.html" %}{% block title %}Contas | Gestao de Acessos{% endblock %}{% block content %}<section class="hero compact"><p class="eyebrow">Administracao</p><h1>Contas do sistema</h1><p>Crie gestores e vincule cada conta ao departamento correto.</p></section><form class="panel account-form" method="post"><input name="name" placeholder="Nome" required><input name="email" type="email" placeholder="E-mail" required><input name="password" type="password" placeholder="Senha inicial" minlength="10" required><select name="role"><option value="GESTOR_DEPARTAMENTO">Gestor de departamento</option><option value="ANALISTA_TI">Analista T.I.</option><option value="ADMIN_TI">Admin T.I.</option></select><select name="department_id"><option value="">Sem departamento</option>{% for d in departments %}<option value="{{ d.id }}">{{ d.nome }}</option>{% endfor %}</select><button class="primary">Criar conta</button></form><section class="proposal-list">{% for account in users %}<article><div><strong>{{ account.name }}</strong><span>{{ account.email }} · {{ account.role|replace('_',' ')|title }}</span></div><em>{{ account.department.nome if account.department else 'Todos os departamentos' }}</em></article>{% endfor %}</section>{% endblock %}''',
'portal_profiles.html': '''{% extends "base.html" %}{% block title %}Perfis | Gestao de Acessos{% endblock %}{% block content %}<section class="hero compact"><p class="eyebrow">Perfis importados do ERP</p><h1>Perfis do departamento</h1><p>{% if user.department %}Perfis atualmente utilizados por funcionarios de {{ user.department.nome }}.{% else %}Perfis disponíveis para T.I.{% endif %}</p></section><section class="people-grid">{% for p in profiles %}<a class="person-card" href="/portal/perfis/{{ p.id }}"><strong>{{ p.nome }}</strong><span>{{ p.situacao }}</span><small>Importado do ERP</small></a>{% else %}<article class="panel">Nenhum perfil encontrado.</article>{% endfor %}</section>{% endblock %}''',
'portal_profile.html': '''{% extends "base.html" %}{% block title %}{{ profile.nome }}{% endblock %}{% block content %}<a class="back" href="/portal/perfis">Voltar para perfis</a><section class="hero compact"><p class="eyebrow">Perfil importado do ERP</p><h1>{{ profile.nome }}</h1><p>{{ profile.situacao }}</p></section><section class="panel"><p>Este perfil e somente leitura no portal. Alteracoes devem ser feitas por uma proposta.</p><a class="button" href="/perfis/{{ profile.id }}">Abrir arvore de acessos</a></section>{% endblock %}'''
}

for name, content in portal_templates.items():
    (T / name).write_text(content, encoding='utf-8', newline='\n')

access = ACCESS.read_text(encoding='utf-8')
# Add integrated profile routes before account routes.
marker = "@router.get('/admin/contas'"
profile_routes = '''@router.get('/portal/perfis', response_class=HTMLResponse)\ndef portal_profiles(request: Request, session: Db, user: Annotated[SystemUser, Depends(require_user)]):\n    query = select(Perfil).order_by(Perfil.nome)\n    if user.role == ROLE_MANAGER:\n        query = query.where(Perfil.id.in_(profile_ids_for_department(session, user.department_id)))\n    return templates.TemplateResponse(request=request, name='portal_profiles.html', context={'user': user, 'profiles': session.scalars(query).all()})\n\n\n@router.get('/portal/perfis/{profile_id}', response_class=HTMLResponse)\ndef portal_profile_detail(request: Request, profile_id: int, session: Db, user: Annotated[SystemUser, Depends(require_user)]):\n    profile = session.get(Perfil, profile_id)\n    if not profile:\n        raise HTTPException(404, 'Perfil nao encontrado')\n    if user.role == ROLE_MANAGER:\n        allowed = session.scalar(select(func.count()).select_from(FuncionarioPerfil).join(Funcionario).where(FuncionarioPerfil.perfil_id == profile_id, Funcionario.departamento_id == user.department_id))\n        if not allowed:\n            raise HTTPException(403, 'Perfil fora do departamento')\n    return templates.TemplateResponse(request=request, name='portal_profile.html', context={'user': user, 'profile': profile})\n\n\n'''
if "@router.get('/portal/perfis'" not in access:
    access = access.replace(marker, profile_routes + marker)
ACCESS.write_text(access, encoding='utf-8', newline='\n')

extra_css = '''\n/* PORTAL_INTEGRADO_V2 */\n.topbar nav{align-items:center}.nav-scope{padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.13);font-size:12px}.logout-form{margin:0}.logout-form button{padding:6px 10px;border:1px solid rgba(255,255,255,.4);background:transparent;color:#fff}.auth-shell{min-height:75vh;display:grid;place-items:center}.auth-card{width:min(430px,94vw);display:grid;gap:14px;padding:30px;background:#fff;border:1px solid #d7e0e8;border-radius:14px;box-shadow:0 18px 50px rgba(18,55,95,.16)}.auth-mark{width:48px;height:48px;display:grid;place-items:center;border-radius:12px;background:#17365d;color:#fff;font-weight:800}.auth-card h1,.auth-card p{margin:0}.auth-card label{display:grid;gap:6px}.auth-card input,.integrated-form input,.integrated-form select,.integrated-form textarea,.account-form input,.account-form select{padding:10px;border:1px solid #aebdca;border-radius:7px}.wide{width:100%}.primary,.button{display:inline-block;padding:9px 13px;border:0;border-radius:7px;background:#1f4e78;color:#fff;text-decoration:none}.portal-metrics article a{display:inline-block;margin-top:8px;color:#1f4e78}.integrated-form{display:grid;grid-template-columns:1fr 1fr;gap:13px}.integrated-form label{display:grid;gap:6px}.integrated-form .full{grid-column:1/-1}.integrated-form textarea{min-height:90px}.alert{padding:10px 12px;border-left:4px solid #d97706;background:#fff8e7}.alert.error{border-color:#dc2626;background:#fff1f0}.proposal-list{display:flex;flex-direction:column;gap:8px;margin-top:12px}.proposal-list>a,.proposal-list>article{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px;background:#fff;border:1px solid #d7e0e8;border-radius:9px;color:#172033;text-decoration:none}.proposal-list span{display:block;margin-top:4px;color:#667085}.flow-status{padding:4px 9px;border-radius:999px;background:#e7edf3;font-style:normal}.flow-status.em_revisao{background:#fff0c2;color:#805700}.flow-status.aprovado{background:#d9fbe3;color:#075b24}.flow-status.rejeitado{background:#ffe0dd;color:#8a1712}.access-list{max-height:580px;overflow:auto}.access-list>div{display:grid;grid-template-columns:1fr auto;gap:10px;padding:8px;border-bottom:1px solid #edf0f2}.permission{padding:3px 8px;border-radius:999px}.permission.permitido{background:#d9fbe3;color:#075b24}.permission.negado{background:#ffe0dd;color:#8a1712}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.review-grid form{display:grid;gap:8px}.review-grid textarea{min-height:90px}.approve{background:#15803d}.return{background:#d97706}.reject{background:#dc2626}.account-form{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.chips a{padding:6px 10px;border-radius:999px;background:#e6f3ff;color:#174d7a;text-decoration:none}@media(max-width:900px){.topbar nav{align-items:flex-start;flex-wrap:wrap}.integrated-form,.review-grid,.account-form{grid-template-columns:1fr}.integrated-form .full{grid-column:auto}.proposal-list>a,.proposal-list>article{align-items:flex-start;flex-direction:column}}\n'''
styles_path = S / 'styles.css'
styles = styles_path.read_text(encoding='utf-8')
if '/* PORTAL_INTEGRADO_V2 */' not in styles:
    styles += extra_css
styles_path.write_text(styles, encoding='utf-8', newline='\n')

py_compile.compile(str(ACCESS), doraise=True)
py_compile.compile(str(MAIN), doraise=True)
print('Portal integrado ao sistema visual existente.')
print('Login, usuarios, perfis, propostas, comparacao e contas agora usam a mesma navegacao.')
